CREATE OR ALTER PROCEDURE [dbo].[uspProofOfDelivery_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @DeliveryOrderId UNIQUEIDENTIFIER = NULL
	, @ConfirmedAt DATETIME2 = NULL
	, @ReceiverName NVARCHAR(MAX) = NULL
	, @ReceiverPhone NVARCHAR(MAX) = NULL
	, @DeliveredQuantity DECIMAL(18,4) = NULL
	, @AcceptedQuantity DECIMAL(18,4) = NULL
	, @RejectedQuantity DECIMAL(18,4) = NULL
	, @SignatureUrl NVARCHAR(MAX) = NULL
	, @PhotoUrl NVARCHAR(MAX) = NULL
	, @Remark NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[DeliveryOrderId]
			, j1.[DeliveryNo] AS [DeliveryOrderName]
			, t.[ReceiverName]
			, t.[ReceiverPhone]
			, t.[ReceivedAt]
			, t.[SignatureUrl]
			, t.[PhotoUrl]
			, t.[Remark]
			, t.[ConfirmedAt]
			, t.[DeliveredQuantity]
			, t.[AcceptedQuantity]
			, t.[RejectedQuantity]
			, t.[CreatedDate]
		FROM [dbo].[ProofOfDeliverie] AS t
		LEFT JOIN [dbo].[DeliveryOrder] AS j1 ON j1.[Id] = t.[DeliveryOrderId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ReceiverName] LIKE CONCAT('%', @SearchText, '%'))
			AND (@DeliveryOrderId IS NULL OR t.[DeliveryOrderId] = @DeliveryOrderId)
			AND (@ConfirmedAt IS NULL OR t.[ConfirmedAt] = @ConfirmedAt)
			AND (ISNULL(@ReceiverName, '') = '' OR t.[ReceiverName] LIKE CONCAT('%', @ReceiverName, '%'))
			AND (ISNULL(@ReceiverPhone, '') = '' OR t.[ReceiverPhone] LIKE CONCAT('%', @ReceiverPhone, '%'))
			AND (@DeliveredQuantity IS NULL OR t.[DeliveredQuantity] = @DeliveredQuantity)
			AND (@AcceptedQuantity IS NULL OR t.[AcceptedQuantity] = @AcceptedQuantity)
			AND (@RejectedQuantity IS NULL OR t.[RejectedQuantity] = @RejectedQuantity)
			AND (ISNULL(@SignatureUrl, '') = '' OR t.[SignatureUrl] LIKE CONCAT('%', @SignatureUrl, '%'))
			AND (ISNULL(@PhotoUrl, '') = '' OR t.[PhotoUrl] LIKE CONCAT('%', @PhotoUrl, '%'))
			AND (ISNULL(@Remark, '') = '' OR t.[Remark] LIKE CONCAT('%', @Remark, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryOrderId' THEN r.[DeliveryOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryOrderId' THEN r.[DeliveryOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryOrderName' THEN r.[DeliveryOrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryOrderName' THEN r.[DeliveryOrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'receiverName' THEN r.[ReceiverName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'receiverName' THEN r.[ReceiverName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'receiverPhone' THEN r.[ReceiverPhone] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'receiverPhone' THEN r.[ReceiverPhone] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'receivedAt' THEN r.[ReceivedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'receivedAt' THEN r.[ReceivedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'signatureUrl' THEN r.[SignatureUrl] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'signatureUrl' THEN r.[SignatureUrl] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'photoUrl' THEN r.[PhotoUrl] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'photoUrl' THEN r.[PhotoUrl] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'remark' THEN r.[Remark] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'remark' THEN r.[Remark] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'confirmedAt' THEN r.[ConfirmedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'confirmedAt' THEN r.[ConfirmedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveredQuantity' THEN r.[DeliveredQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveredQuantity' THEN r.[DeliveredQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'acceptedQuantity' THEN r.[AcceptedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'acceptedQuantity' THEN r.[AcceptedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'rejectedQuantity' THEN r.[RejectedQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'rejectedQuantity' THEN r.[RejectedQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
